      "first_actual_publication_id": "P:1:0c328b62-6fdf-4d29-a6fa-2773df5d09b3",
      "valid_publication_id": "P:1:0c328b62-6fdf-4d29-a6fa-2773df5d09b3",
      "first_actual_core_quote": "CREATE_PROPOSAL 업무가 ACCEPTED(접수)되었습니다.",
      "valid_core_quote": "CREATE_PROPOSAL 업무가 ACCEPTED(접수)되었습니다.",
      "wrong_first": false,
      "evidence": [
        "E5077",
        "E5085",
        "P:1:0c328b62-6fdf-4d29-a6fa-2773df5d09b3"
      ],
      "reason": "첫 응답은 현재 요청의 실제 접수를 알렸고 완료되지 않았음도 명시해 endpoint에 맞는 truthful checkpoint였다."
    }
  ],
